// Firebase configuration for ProBridge website
// Project: probridge-447cc

// ─── App Check Debug Token (MUST be set before any Firebase import is used) ───
// This token was generated in Firebase Console → App Check → Apps → Debug tokens
// It tells Firebase App Check to use the debug attestation provider on localhost.
if (process.env.NODE_ENV !== 'production') {
  // eslint-disable-next-line no-restricted-globals
  self.FIREBASE_APPCHECK_DEBUG_TOKEN = '859B1CA9-854B-4BBD-99F4-4B741861DF9D';
}

import { initializeApp } from 'firebase/app';
import { getAuth, initializeRecaptchaConfig } from 'firebase/auth';
import { initializeAppCheck, CustomProvider } from 'firebase/app-check';

const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY || "AIzaSyCNn0pnaLxwv7qia-pApZVhMP8vzR7oKB8",
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN || "probridge-447cc.firebaseapp.com",
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || "probridge-447cc",
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET || "probridge-447cc.firebasestorage.app",
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID || "145417779758",
  appId: process.env.REACT_APP_FIREBASE_APP_ID || "1:145417779758:web:42b24fb652ebe83a267dbf",
  measurementId: process.env.REACT_APP_FIREBASE_MEASUREMENT_ID || "G-29NX7FWEL0",
};

const app = initializeApp(firebaseConfig);

// ─── App Check ────────────────────────────────────────────────────────────────
// In development: FIREBASE_APPCHECK_DEBUG_TOKEN (set above) is automatically
// detected by Firebase and used instead of the custom provider below.
// In production: replace CustomProvider with ReCaptchaV3Provider + site key.
try {
  initializeAppCheck(app, {
    provider: new CustomProvider({
      getToken: () =>
        Promise.resolve({
          token: process.env.REACT_APP_APPCHECK_DEBUG_TOKEN || '859B1CA9-854B-4BBD-99F4-4B741861DF9D',
          expireTimeMillis: Date.now() + 60 * 60 * 1000,
        }),
    }),
    isTokenAutoRefreshEnabled: true,
  });
} catch (e) {
  // App Check already initialized (HMR / hot reload)
}

// ─── Auth ─────────────────────────────────────────────────────────────────────
export const auth = getAuth(app);

// Properly negotiate reCAPTCHA Enterprise vs v2 — prevents auth/invalid-app-credential
initializeRecaptchaConfig(auth).catch(() => {
  // Non-fatal: falls back to reCAPTCHA v2 automatically
});

export default app;
